from pathlib import Path

p=Path('market.js')
s=p.read_text(encoding='utf-8')

anchor='''  function scoreBand(value){\n    const v=n(value);\n    if(v==null) return 'Sem score publicável';\n    if(v>=75) return 'Muito forte no ranking';\n    if(v>=60) return 'Acima da média';\n    if(v>=40) return 'Intermédio';\n    return 'Abaixo da média';\n  }\n\n'''
insert='''  function scoreBand(value){\n    const v=n(value);\n    if(v==null) return 'Sem score publicável';\n    if(v>=75) return 'Muito forte no ranking';\n    if(v>=60) return 'Acima da média';\n    if(v>=40) return 'Intermédio';\n    return 'Abaixo da média';\n  }\n\n  const SCORE_MODEL_WEIGHTS={\n    general:[['Qualidade',18],['Crescimento',15],['Balanço',14],['Cash flow',8],['Valuation',12],['Execução',10],['Qualidade dos lucros',10],['Alocação de capital',8],['Estabilidade',5]],\n  };\n  function scoreModelMethod(s){\n    const model=txt(s?.score_model)||'general';\n    const notes={\n      general:'Modelo geral: combina qualidade operacional, crescimento, balanço, cash flow, valuation, execução, qualidade dos lucros, alocação de capital e estabilidade.',\n      bank:'Modelo bancário: dá prioridade a rentabilidade, valor contabilístico, eficiência, provisões e solidez de capital; métricas industriais de dívida têm menos significado.',\n      insurance:'Modelo de seguros: privilegia rentabilidade, valor contabilístico, claims/benefícios, eficiência operacional e capitalização.',\n      reit:'Modelo REIT: privilegia FFO/P-FFO, dívida, distribuição e métricas imobiliárias. Quando AFFO/NAV não existem, o Vestra identifica explicitamente os proxies.',\n      utility:'Modelo utilities: dá maior importância a balanço, cash flow, estabilidade e rendimento, por serem negócios intensivos em capital.',\n      energy:'Modelo energia: enfatiza geração de caixa, balanço e valuation cíclico; um múltiplo baixo isolado não é tratado automaticamente como oportunidade.',\n      biotech:'Modelo biotech: evita premiar múltiplos inexistentes em empresas pré-lucro e aceita que a avaliação fique insuficiente sem evidência económica comparável.',\n      growth_tech:'Modelo tecnologia/crescimento: aumenta a relevância de crescimento, qualidade, execução, forward earnings e geração de caixa.'\n    };\n    return notes[model]||notes.general;\n  }\n  function scoreWeightSummary(s){\n    const model=txt(s?.score_model)||'general';\n    const pack=SCORE_MODEL_WEIGHTS[model];\n    if(!pack) return '';\n    return `<div class="market-watchpoints">${pack.map(([label,w])=>`<span>${esc(label)} · ${w}%</span>`).join('')}</div>`;\n  }\n  function evaluationGuide(s){\n    const score=n(s?.score), coverage=n(s?.data_coverage_pct), conf=n(s?.confidence_score);\n    const risk=txt(s?.risk_gate)||'clear';\n    const val=txt(s?.valuation_signal)||'insufficient';\n    const valLabel={undervalued:'abaixo da faixa peer-relative',fair:'próximo da faixa peer-relative',overvalued:'acima da faixa peer-relative',uncertain:'valuation não acionável',insufficient:'valuation insuficiente'}[val]||val;\n    const riskLabel={clear:'sem bloqueio estrutural',watch:'risco a vigiar',high:'risco elevado',severe:'risco severo'}[risk]||risk;\n    return `<div class="market-detail-card market-evaluation-guide"><div class="market-perspective-head"><div><small>COMO LER AS AVALIAÇÕES</small><h4>Três perguntas diferentes</h4></div><span class="market-data-age">não somar mecanicamente</span></div><div class="market-mini-grid"><div><small>1 · Empresa</small><strong>Score ${score==null?'—':Math.round(score)+'/100'}</strong><span>Quão forte é o negócio no ranking relativo do modelo.</span></div><div><small>2 · Preço</small><strong>${esc(valLabel)}</strong><span>Compara o preço com múltiplos/yields de pares; não é um target.</span></div><div><small>3 · Evidência</small><strong>${coverage==null?'Cobertura —':'Cobertura '+Math.round(coverage)+'%'}</strong><span>Quanto dos dados necessários está realmente disponível.</span></div><div><small>4 · Risco</small><strong>${esc(riskLabel)}</strong><span>Pode limitar a leitura mesmo quando score ou valuation parecem atraentes.</span></div></div>${conf!=null?`<p class="market-case-note">Confidence score ${Math.round(conf)}/100 resume força/completude da evidência; não é probabilidade de valorização.</p>`:''}</div>`;\n  }\n\n'''
if s.count(anchor)!=1: raise SystemExit(f'scoreBand anchor mismatch: {s.count(anchor)}')
s=s.replace(anchor,insert,1)

old='''    return `<div class="market-detail-card market-score-explain"><div class="market-perspective-head"><div><small>PORQUE TEM ESTE SCORE</small><h4>${Math.round(score)}/100 · ${esc(scoreBand(score))}</h4></div><span class="market-data-age">${esc(scoreModelLabel(s.score_model))}</span></div><p><strong>O Score Vestra é um ranking relativo de qualidade, crescimento, balanço, cash flow, valuation e outros fatores — não é uma previsão de retorno.</strong> Um pilar em 80 significa aproximadamente que a empresa está perto do percentil 80 no conjunto comparável usado pelo modelo; não significa 80% de probabilidade de subir.</p>${strongest.length?`<p class="market-case-note">A puxar para cima: ${pair(strongest)}.</p>`:''}${weakest.length?`<p class="market-case-note">A limitar a avaliação: ${pair(weakest)}.</p>`:''}<div class="market-action-context"><span>Cobertura ${coverage==null?'—':Math.round(coverage)+'%'}</span><span>Confiança ${esc(confidence)}</span><span>${dims.length}/9 pilares disponíveis</span></div><p class="market-case-note">Valores ausentes não são tratados como zero. Os pesos dos pilares disponíveis são renormalizados; por isso scores com coberturas muito diferentes devem ser comparados com cautela.</p></div>`;\n'''
new='''    return `<div class="market-detail-card market-score-explain"><div class="market-perspective-head"><div><small>PORQUE TEM ESTE SCORE</small><h4>${Math.round(score)}/100 · ${esc(scoreBand(score))}</h4></div><span class="market-data-age">${esc(scoreModelLabel(s.score_model))}</span></div><p><strong>O Score Vestra mede posição relativa, não retorno esperado.</strong> Um score 75–80 significa que a combinação dos pilares disponíveis é forte face ao universo comparável; não significa 75–80% de upside, nem essa probabilidade de a ação subir.</p><p class="market-case-note">${esc(scoreModelMethod(s))}</p>${scoreWeightSummary(s)}${strongest.length?`<p class="market-case-note">A puxar para cima: ${pair(strongest)}.</p>`:''}${weakest.length?`<p class="market-case-note">A limitar a avaliação: ${pair(weakest)}.</p>`:''}<div class="market-action-context"><span>Cobertura ${coverage==null?'—':Math.round(coverage)+'%'}</span><span>Confiança ${esc(confidence)}</span><span>${dims.length}/9 pilares disponíveis</span></div><p class="market-case-note">Cada pilar também é relativo: percentil 80 significa melhor posicionamento que aproximadamente 80% do conjunto comparado nessa dimensão. Valores ausentes não são tratados como zero. Os pesos dos pilares disponíveis são renormalizados; por isso scores com coberturas muito diferentes devem ser comparados com cautela.</p></div>`;\n'''
if s.count(old)!=1: raise SystemExit(f'score explanation anchor mismatch: {s.count(old)}')
s=s.replace(old,new,1)

old_overview='''    if(tab==='overview') body.innerHTML=`${changePanel(s)}${recoveryPanel(s)}${drawdownPanel(s)}${catalystPanel(s)}${investmentCase(s)}${scoreExplanation(s)}<details class="market-detail-disclosure"><summary>Ver pilares e detalhe quantitativo</summary>'''
new_overview='''    if(tab==='overview') body.innerHTML=`${changePanel(s)}${recoveryPanel(s)}${drawdownPanel(s)}${catalystPanel(s)}${investmentCase(s)}${evaluationGuide(s)}${scoreExplanation(s)}<details class="market-detail-disclosure"><summary>Ver pilares e detalhe quantitativo</summary>'''
if s.count(old_overview)!=1: raise SystemExit(f'overview anchor mismatch: {s.count(old_overview)}')
s=s.replace(old_overview,new_overview,1)

old_val='''${methods.length?`<div class="market-watchpoints">${methods.slice(0,4).map(x=>`<span>${esc(x.method)} · ${money(x.fair_value,s.currency)}</span>`).join('')}</div>`:''}</div><div class="market-detail-card"><h4>Múltiplos</h4>'''
new_val='''${methods.length?`<div class="market-watchpoints">${methods.slice(0,5).map(x=>`<span>${esc(x.method)} · ${money(x.fair_value,s.currency)}${n(x.weight)!=null?` · peso ${num(x.weight)}x`:''}</span>`).join('')}</div>`:''}<p class="market-case-note"><strong>Como é construída:</strong> cada método converte o múltiplo/yield atual numa estimativa implícita usando a mediana do setor. O centro combina média ponderada e mediana; a faixa alarga quando os métodos discordam. Quality/Growth só podem ajustar modestamente o centro nos modelos Geral e Tecnologia/Crescimento.</p><p class="market-case-note"><strong>Como interpretar:</strong> “undervalued” exige pelo menos +25% até ao centro; “overvalued” começa em −20%. Risk Gate alto/severo ou confidence score abaixo de 50 transforma a leitura em “uncertain”, mesmo que a matemática pareça barata.</p></div><div class="market-detail-card"><h4>Múltiplos</h4>'''
if s.count(old_val)!=1: raise SystemExit(f'valuation anchor mismatch: {s.count(old_val)}')
s=s.replace(old_val,new_val,1)

p.write_text(s,encoding='utf-8')

t=Path('tests/test_market_evaluation_explainability_v2.py')
t.write_text('''from pathlib import Path\nimport unittest\n\nROOT=Path(__file__).resolve().parents[1]\n\nclass MarketEvaluationExplainabilityV2Tests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.market=(ROOT/'market.js').read_text(encoding='utf-8')\n\n    def test_score_probability_confusion_is_explicitly_rejected(self):\n        self.assertIn('não significa 75–80% de upside', self.market)\n        self.assertIn('percentil 80 significa melhor posicionamento', self.market)\n\n    def test_evaluation_layers_are_separated(self):\n        self.assertIn('COMO LER AS AVALIAÇÕES', self.market)\n        self.assertIn('1 · Empresa', self.market)\n        self.assertIn('2 · Preço', self.market)\n        self.assertIn('3 · Evidência', self.market)\n        self.assertIn('4 · Risco', self.market)\n\n    def test_general_weights_are_visible(self):\n        self.assertIn("['Qualidade',18]", self.market)\n        self.assertIn("['Crescimento',15]", self.market)\n        self.assertIn("['Valuation',12]", self.market)\n        self.assertIn("['Estabilidade',5]", self.market)\n\n    def test_specialist_models_are_explained(self):\n        for phrase in ('Modelo bancário:', 'Modelo de seguros:', 'Modelo REIT:', 'Modelo biotech:', 'Modelo tecnologia/crescimento:'):\n            self.assertIn(phrase, self.market)\n\n    def test_valuation_method_and_thresholds_are_explained(self):\n        self.assertIn('peso ${num(x.weight)}x', self.market)\n        self.assertIn('média ponderada e mediana', self.market)\n        self.assertIn('“undervalued” exige pelo menos +25%', self.market)\n        self.assertIn('confidence score abaixo de 50', self.market)\n\nif __name__ == '__main__':\n    unittest.main(verbosity=2)\n''',encoding='utf-8')
